    coCards:[{badge:'تقديم العروض',rate:'0',line:'مجاني وغير محدود',desc:'تصفّح وقدّم عروضك على ما تشاء من المشاريع. لا تُحتسب رسوم إلا على العمل الذي تفوز به.'},{badge:'رسوم خدمة المقاول',rate:'⁦9%⁩',line:'من قيمة العمل المتفق عليها، تُخصم من كل دفعة مرحلية للمقاول',desc:'تُحتسب دون ضريبة القيمة المضافة ودون المواد التي يشتريها صاحب المنزل بنفسه. لا يُحتسب شيء عند التوقيع؛ تُسوَّى رسوم الخدمة مع صرف كل دفعة.'}],
